import json

def tileable(n):
    # Area must be divisible by 3 for L-tromino tiling.
    if (n * n) % 3:
        return False
    g = [[False] * n for _ in range(n)]

    def first_empty():
        for i in range(n):
            for j in range(n):
                if not g[i][j]:
                    return i, j
        return None

    def solve():
        p = first_empty()
        if p is None:
            return True
        i, j = p
        # Any L-tromino covering (i, j) lies in a 2x2 block whose top-left is (r, c).
        for r in (i - 1, i):
            for c in (j - 1, j):
                if r < 0 or c < 0 or r + 1 >= n or c + 1 >= n:
                    continue
                block = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
                for omit in block:
                    cells = [x for x in block if x != omit]
                    if (i, j) not in cells:
                        continue
                    if any(g[x][y] for x, y in cells):
                        continue
                    for x, y in cells:
                        g[x][y] = True
                    if solve():
                        return True
                    for x, y in cells:
                        g[x][y] = False
        return False

    return solve()

sides = list(range(1, 9))
results = {n: tileable(n) for n in sides}
tileable_sides = [n for n in sides if results[n]]
failing_sides = [n for n in sides if not results[n]]

some_square = len(tileable_sides) > 0
every_square = len(failing_sides) == 0
smallest = tileable_sides[0] if tileable_sides else None
example_fail = failing_sides[0] if failing_sides else None

if some_square and not every_square:
    final = (f"Yes, some square can be formed (smallest side {smallest}); "
             f"not every square can (side {example_fail} is impossible).")
elif some_square and every_square:
    final = "Yes, every square can be formed."
else:
    final = "No square can be formed within the checked range."

out = {
    "final_answer": final,
    "evidence": {
        "checked_sides": sides,
        "tileable": {str(n): results[n] for n in sides},
        "smallest_tileable_side": smallest,
        "smallest_failing_side": example_fail,
        "some_square_possible": some_square,
        "every_square_possible": every_square,
    },
}
print(json.dumps(out, separators=(",", ":")))
